const ids = ["GHSA-356w-63v5-8wf4", "GHSA-4r4m-qw57-chr8"];
for (const id of ids) {
  const gh = await fetch(`https://api.github.com/advisories/${id}`, {headers:{"User-Agent":"review","Accept":"application/vnd.github+json"}});
  const j = await gh.json();
  console.log("=== GITHUB", id, "===");
  console.log("  summary      :", j.summary);
  console.log("  cve          :", j.cve_id);
  console.log("  severity     :", j.severity);
  for (const v of (j.vulnerabilities||[])) {
    console.log("  package      :", v.package?.name, "| ecosystem:", v.package?.ecosystem);
    console.log("  vulnerable_range:", v.vulnerable_version_range);
    console.log("  first_patched:", v.first_patched_version?.identifier);
  }
  const osv = await fetch(`https://api.osv.dev/v1/vulns/${id}`);
  if (osv.ok) {
    const o = await osv.json();
    console.log("  -- OSV --");
    for (const a of (o.affected||[])) {
      for (const r of (a.ranges||[])) console.log("   ", a.package?.name, JSON.stringify(r.events));
    }
  } else { console.log("  OSV lookup failed", osv.status); }
  console.log();
}

